// ============================================================
// PayrollLogos.cs
// Logos are embedded as transparent PNG Base64 strings.
// Black background has been removed from both images.
//
// Positioning:
//   NCSC    — left  of the header title text  (col 2, row 3)
//   Bagong  — right of the header title text  (col 17, row 3)
//
// The header title is centered on cols 4–16 (MergeCenter calls
// in BuildPayrollSheet use col 11 which is the center of B–S).
// Placing logos at col 2 (left edge of title area) and col 17
// (right edge of title area) puts them snug beside the text.
// ============================================================
using ClosedXML.Excel;
using ClosedXML.Excel.Drawings;

public static class PayrollLogos
{
    internal static readonly string NcscBase64  =
        "";

    internal static readonly string BagongBase64  =
        "";

    /// <summary>
    /// Adds NCSC logo (left) and Bagong Pilipinas logo (right)
    /// beside the centered header title text.
    ///
    /// Call this AFTER ws.Row(11).Height = 11.25 and BEFORE
    /// the NavyHeader / column-header calls (Section 2).
    ///
    /// widthPx / heightPx — logo size in pixels (default 72x72).
    /// offsetLeft  — extra px to push NCSC logo rightward toward text.
    /// offsetRight — extra px to push Bagong logo leftward toward text.
    /// </summary>
    // ✅ UPDATED defaults:
    public static void AddLogos(
        IXLWorksheet ws,
        int anchorRow = 3,
        int leftCol = 2,
        int rightCol = 19,
        int widthPx = 95,
        int heightPx = 95,
        int offsetLeft = 4,
        int offsetRight = 251)  // ✅ was 245, now 251
    {
        // ── LEFT: NCSC seal ──────────────────────────────────────────────
        // Anchored at row 3, col 2 (column B) — immediately left of the
        // title area.  The small offsetLeft nudges it toward the text.
        using var ncscStream = new MemoryStream(
            Convert.FromBase64String(NcscBase64));

        ws.AddPicture(ncscStream, XLPictureFormat.Png)
          .MoveTo(ws.Cell(anchorRow, leftCol), offsetLeft, 2)
          .WithSize(widthPx, heightPx);

        // ── RIGHT: Bagong Pilipinas ──────────────────────────────────────
        // Anchored at row 3, col 17 (column Q) — immediately right of the
        // title area.  A negative offsetRight is not supported by ClosedXML
        // so we use col 18 with a small positive offset instead,
        // which visually reads as "right beside the title".
        using var bagongStream = new MemoryStream(
            Convert.FromBase64String(BagongBase64));

        // Col 19 width = 50.0 "character units"
        // 1 character unit ≈ 7px at 96dpi
        // Col 19 width in px ≈ 50 × 7 = 350px
        // Logo width = 72px
        // Offset to right-align = 350 - 72 - 4 (margin) = 274px

        ws.AddPicture(bagongStream, XLPictureFormat.Png)
          .MoveTo(ws.Cell(anchorRow, rightCol), offsetRight, 2)
          .WithSize(widthPx, heightPx);


    }
}